{"rob": "robolang 1.3;

task transfer(robot r, object box, location src, location dst, region cell) {
    goal { object_at box dst; }
    plan {
        wait until region_clear cell timeout 30 s;
        move r to src;
        grasp r box;
        move r to dst;
        place r box at dst;
    }
}
